const ICONS={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',path:'<path d="m4 18 5-5 4 3 7-10"/><circle cx="4" cy="18" r="2"/><circle cx="9" cy="13" r="2"/><circle cx="13" cy="16" r="2"/><circle cx="20" cy="6" r="2"/>',book:'<path d="M12 7v14m0-14C8 4 5 5 3 5v14c3-1 6-1 9 2m0-14c4-3 7-2 9-2v14c-3-1-6-1-9 2"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-4 0h8"/>',headphones:'<path d="M3 14v-3a9 9 0 0 1 18 0v3"/><rect x="2" y="13" width="5" height="8" rx="2"/><rect x="17" y="13" width="5" height="8" rx="2"/>',practice:'<path d="m9 12 2 2 4-4"/><circle cx="12" cy="12" r="9"/>',chart:'<path d="M4 20V10m6 10V4m6 16v-7m5 7V8M2 21h21"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',left:'<path d="M19 12H5m6 6-6-6 6-6"/>',check:'<path d="m4 12 5 5L20 6"/>',play:'<path d="m8 5 11 7-11 7V5Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/>',moon:'<path d="M21 12.7A9 9 0 0 1 11.3 3a9 9 0 1 0 9.7 9.7Z"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="M5 5 19 19M19 5 5 19"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',flame:'<path d="M12 22c-5 0-7-3-7-7 0-5 5-8 4-12 6 3 4 7 7 8 1-2 1-3 1-4 7 8 3 15-5 15Z"/>',award:'<circle cx="12" cy="8" r="5"/><path d="m8 12-2 10 6-3 6 3-2-10"/>',layers:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8m-8 4h8"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',upload:'<path d="M12 21V9m-4 4 4-4 4 4M4 7V3h16v4"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',edit:'<path d="m4 20 4-1 12-12-3-3L5 16l-1 4Z"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7v.01"/>',heart:'<path d="M20 5a5 5 0 0 0-7 0l-1 1-1-1a5 5 0 1 0-7 7l8 9 8-9a5 5 0 0 0 0-7Z"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',repeat:'<path d="M4 7h14l-3-3m3 3-3 3M20 17H6l3-3m-3 3 3 3"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 7 9-7"/>'};
function icon(name,size=19){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.info}</svg>`;}
const e=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const navs=[['dashboard','Главная','dashboard'],['path','Программа','path'],['vocabulary','Словарь','book'],['conversation','Conversation Lab','mic'],['listening','Listening Studio','headphones'],['practice','Практика','practice'],['progress','Прогресс','chart'],['phrasebook','Phrasebook','layers'],['emails','Email templates','mail'],['settings','Настройки','settings']];
const num=n=>Number(n||0).toLocaleString('ru-RU');
const bar=(v,label)=>`<div class="micro-progress" role="progressbar" aria-label="${e(label)}" aria-valuenow="${v}" aria-valuemin="0" aria-valuemax="100"><span style="width:${Math.min(100,Math.max(0,v))}%"></span></div>`;
const route=()=>decodeURIComponent((location.hash||'#dashboard').slice(1).split('?')[0]);
const currentDay=()=>D.lessons.find(l=>!state.lessons[l.id]?.completedAt)?.day||30;
const getLesson=(day)=>D.lessons[Number(day)-1];
const lessonState=day=>C.lessonState(state,day);
const save=()=>{if(storageBlocked)return;try{C.persist(localStorage,state);loadError='';}catch(err){toast('Не удалось сохранить данные: проверьте доступное место в браузере.',true);}};
function applyTheme(){document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('big-type',state.fontScale==='large');}
function goto(to){location.hash=to;if(route()===to)render();}
function toast(message,bad=false){clearTimeout(ui.toastTimeout);const old=document.getElementById('toast');if(old)old.remove();const node=document.createElement('div');node.id='toast';node.className='toast'+(bad?' bad':'');node.setAttribute('role','status');node.textContent=message;document.body.appendChild(node);ui.toastTimeout=setTimeout(()=>node.remove(),4300);}
function header(title){const s=C.stats(state,D);return `<div class="topbar"><div class="row"><button class="icon-btn mobile-menu-btn" aria-label="Открыть меню" data-action="drawer">${icon('menu')}</button><span class="top-title">${e(title)} <span class="muted">/ Academic English</span></span></div><div class="top-actions"><span class="top-chip">${icon('flame',15)} ${s.streak} days</span><span class="top-chip">${icon('spark',15)} ${num(s.xp)} XP</span><button class="icon-btn" data-action="theme-cycle" aria-label="Сменить тему">${icon(state.theme==='dark'?'sun':'moon')}</button></div></div>`;}
function sidebar(){const s=C.stats(state,D);return `<aside class="sidebar" aria-label="Основная навигация"><button class="logo" data-route="dashboard"><span class="logo-mark">A<b>.</b></span><span class="brand">Academic English<span class="brand-sub">Learning studio</span></span></button><p class="nav-group-label">Learning space</p><div class="nav-list">${navs.slice(0,7).map(([r,name,i])=>`<button class="nav-item ${route().split('/')[0]===r?'active':''}" data-route="${r}">${icon(i)}<span>${e(name)}</span>${r==='vocabulary'&&s.due?`<span class="nav-count">${s.due}</span>`:''}</button>`).join('')}</div><p class="nav-group-label">Resources</p><div class="nav-list">${navs.slice(7).map(([r,name,i])=>`<button class="nav-item ${route()===r?'active':''}" data-route="${r}">${icon(i)}<span>${e(name)}</span></button>`).join('')}</div><div class="sidebar-bottom"><div class="sidebar-info"><strong>Ваш учебный маршрут</strong><p>30 дней · International Academic Support</p>${bar(Math.round(s.finished/30*100),'Общий прогресс')}<span class="tiny" style="display:block;margin-top:10px;color:var(--mint-ink)">${s.finished} / 30 уроков</span></div><p class="copyright">ACLS · Offline-first · © 2026</p></div></aside>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="Мобильная навигация">${[['dashboard','Главная','dashboard'],['path','Уроки','path'],['vocabulary','Слова','book'],['practice','Практика','practice'],['progress','Прогресс','chart']].map(([r,label,i])=>`<button class="${route().split('/')[0]===r?'active':''}" data-route="${r}">${icon(i)}<span>${label}</span></button>`).join('')}</nav>`;}
function shell(content,title='Learning space'){return `<div class="shell">${sidebar()}<div class="app-right">${header(title)}<main class="page ${route().startsWith('lesson/')?'lesson-page':''}" id="content" tabindex="-1">${content}</main></div>${mobileNav()}</div>${ui.drawer?`<div class="mobile-drawer" data-action="drawer"><div onclick="event.stopPropagation()">${sidebar()}<button class="icon-btn drawer-close" data-action="drawer" aria-label="Закрыть меню">${icon('close')}</button></div></div>`:''}${ui.modal?modal():''}`;}
function pageHeading(eyebrow,title,desc,actions=''){return `<div class="page-header"><div><span class="eyebrow">${e(eyebrow)}</span><h1>${e(title)}</h1><p>${e(desc)}</p></div>${actions}</div>`;}
function dashboard(){const s=C.stats(state,D),day=currentDay(),l=getLesson(day),done=state.lessons[l.id]?.completedAt,review=s.due;const stats=[['Пройдено уроков',`${s.finished}<span class="muted">/30</span>`,'Из 5 учебных модулей','path'],['Точность ответов',s.accuracy===null?'—':`${s.accuracy}%`,`${s.measured} проверенных заданий`,'practice'],['Слова на повторение',String(review),`${s.totalReviewed} слов уже в системе`,'vocabulary'],['Серия занятий',String(s.streak),`Дней с реальной практикой`,'progress']];return `<div class="hero"><div class="hero-copy"><span class="eyebrow">Academic communication · 30-day programme</span><h1>${s.finished===30?'A stronger voice, every day.':'English for the work you do.'}</h1><p>От знакомства с иностранными коллегами до академических совещаний. Каждый день — реальные ситуации международного университета.</p><button class="btn" data-route="lesson/${day}">${icon('play',17)} ${s.finished===30?'Повторить последний урок':`Продолжить · День ${day}`}</button><div class="hero-meta"><span>◷ ~70 минут в день</span><span>○ B1 → B1+ / toward B2</span><span>✦ Без регистрации</span></div></div><div class="hero-art" aria-hidden="true"><div class="hero-halo"></div><div class="hero-paper"><div class="paper-accent"></div><div class="paper-dash"></div><div class="paper-dash"></div><div class="paper-dash"></div></div><div class="hero-letter">Aa</div></div></div>${loadError?`<div class="feedback wrong">${e(loadError)}</div>`:''}<div class="grid-four">${stats.map(([label,value,desc,target])=>`<button class="card stat-card" data-route="${target}" style="text-align:left;width:100%;cursor:pointer"><span class="stat-label">${e(label)}</span><div class="stat-number">${value}</div><span class="stat-foot">${e(desc)}</span></button>`).join('')}</div><div class="section-heading"><div><h2>Your next step</h2><p>Одна цель за раз. Продолжайте там, где остановились.</p></div><button class="link-btn" data-route="path">Все уроки ${icon('arrow',15)}</button></div><div class="card continue-card"><div><span class="module-tag">Module ${l.module+1} · Day ${l.day}</span><h3>${e(l.title)}</h3><p class="muted">${e(l.titleRu)} · ${e(l.focus)}</p><div style="margin:19px 0">${bar(Math.min(100,Math.round((state.lessons[l.id]?.doneStages?.length||0)/10*100)),'Прогресс текущего урока')}</div><button class="btn primary" data-route="lesson/${l.day}">${icon('arrow',17)} Открыть урок</button></div><div class="continue-aside"><div class="big-day">${String(l.day).padStart(2,'0')}</div><div class="day-txt">of 30 days</div></div></div><div class="section-heading"><div><h2>Daily practice</h2><p>Повторяйте, слушайте и говорите самостоятельно.</p></div></div><div class="grid-three"><div class="lesson-mini"><span class="step-label">Vocabulary · Active recall</span><h3>${review?`Сегодня ожидают ${review} карточек`:'Повторите изученные выражения'}</h3><button class="link-btn" data-route="vocabulary">Повторять ${icon('arrow',15)}</button></div><div class="lesson-mini"><span class="step-label">Speaking · Role play</span><h3>Отработайте разговор с зарубежным коллегой</h3><button class="link-btn" data-route="conversation">Conversation Lab ${icon('arrow',15)}</button></div><div class="lesson-mini"><span class="step-label">Listening · Workplace</span><h3>Послушайте диалог в академическом отделе</h3><button class="link-btn" data-route="listening">Listening Studio ${icon('arrow',15)}</button></div></div><div class="section-heading"><div><h2>Five practical modules</h2><p>От everyday communication до сложных рабочих ситуаций.</p></div></div><div class="grid-three">${D.modules.map((m,i)=>`<button class="module-tile tile-${m.color}" data-route="path" style="text-align:left;cursor:pointer"><h3>${e(m.name)}</h3><p>${e(m.sub)}</p><span class="module-no">MODULE 0${i+1} · DAYS ${m.days[0]}–${m.days[1]}</span></button>`).join('')}</div>`;}
function learningPath(){return pageHeading('Your curriculum','30 days. Real situations.','Пять последовательных модулей. Открывайте любой урок, повторяйте пройденное и сохраняйте прогресс.')+D.modules.map((m,i)=>{const ls=D.lessons.filter(l=>l.module===i),done=ls.filter(l=>state.lessons[l.id]?.completedAt).length;return `<section class="path-module"><div class="module-header"><div class="module-index">0${i+1}</div><div><h2>${e(m.name)}</h2><p>${e(m.sub)}</p></div><span class="module-score">${done} / ${ls.length}</span></div><div class="path-grid">${ls.map(l=>{const st=state.lessons[l.id],percent=st?.completedAt?100:Math.round((st?.doneStages?.length||0)/10*100);return `<button class="path-lesson" data-route="lesson/${l.day}"><div class="path-top"><span>DAY ${String(l.day).padStart(2,'0')}</span><span class="badge ${st?.completedAt?'good':percent?'pending':''}">${st?.completedAt?'✓ Завершён':percent?`${percent}%`:'Доступен'}</span></div><h3>${e(l.title)}</h3><p>${e(l.titleRu)}</p><div class="path-status">${percent?'Продолжить':'Начать'} ${icon('arrow',14)}</div></button>`;}).join('')}</div>${[5,10,15,22].includes(m.days[1])?`<div class="row wrap" style="justify-content:flex-end;margin-top:14px"><button class="btn secondary" data-route="assessment/checkpoint-${m.days[1]}">${icon('practice',17)} Проверка модуля</button></div>`:''}</section>`;}).join('');}
function getStep(day){const pieces=route().split('/');return pieces[2]!==undefined?Math.min(10,Math.max(0,Number(pieces[2])||0)):lessonState(day).stage;}
function exerciseById(day,id){const all=C.getLessonExercises(getLesson(day));return Object.values(all).flat().find(x=>x.id===id);}
function lessonStatus(day,step){const l=getLesson(day),saved=lessonState(day),ex=C.getLessonExercises(l);const attempted=items=>items.every(q=>saved.answers[q.id]);
 if(step===3&&!attempted(ex.reading))return 'Ответьте на вопросы по тексту. Ошибки не блокируют прохождение.';
 if(step===5&&!attempted(ex.listening))return 'Сначала ответьте на вопросы после прослушивания.';
 if(step===6&&!saved.answers[ex.grammar[0].id])return 'Сначала выполните грамматическое задание.';
 if(step===7&&ex.practice.filter(q=>saved.answers[q.id]||saved.writing?.[q.id]).length<3)return 'Для продолжения выполните три разных упражнения.';
 if(step===8&&!saved.speaking?.practised)return 'Произнесите ответ, затем выполните самопроверку и отметьте практику.';
 if(step===9&&!saved.writing?.practised)return 'Составьте рабочий ответ и проведите самопроверку.';
 return '';
}
function lessonView(day){const l=getLesson(day);if(!l)return `<div class="empty"><h2>Урок не найден</h2><button class="btn primary" data-route="path">Вернуться к программе</button></div>`;
 const record=lessonState(day),step=getStep(day);const gate=step>record.stage&&!record.completedAt;
 const status=record.completedAt?'Completed':`${Math.max(0,record.doneStages.length)} / 10 sections`;
 return `<div class="lesson-head"><button class="link-btn" data-route="path">${icon('left',14)} Все уроки</button><div class="row wrap" style="margin-top:11px"><span class="badge accent">MODULE 0${l.module+1} · DAY ${String(day).padStart(2,'0')}</span><span class="badge">${e(status)}</span></div><h1>${e(l.title)}</h1><p>${e(l.titleRu)} · ${e(l.focus)}</p></div><div class="lesson-layout"><nav class="step-sidebar" aria-label="Этапы урока"><p class="step-title">Your lesson</p>${C.stages.map((st,i)=>`<button class="step-link ${i===step?'current':''} ${record.doneStages.includes(i)?'done':''}" data-action="lesson-step" data-day="${day}" data-step="${i}" ${i>record.stage&&!record.completedAt?'disabled':''}><span class="step-dot">${record.doneStages.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span>${e(st)}</span></button>`).join('')}<div class="step-progress">${bar(Math.min(100,record.doneStages.length*10),'Урок')}</div><p class="step-cnt">${record.doneStages.length} из 10 этапов завершено</p></nav><div class="lesson-main"><section class="lesson-section">${gate?`<div class="notice">Этот этап пока недоступен. Завершите предыдущие этапы.</div><button class="btn primary" data-route="lesson/${day}/${record.stage}">Вернуться</button>`:stageView(l,step)}</section><div class="lesson-nav"><button class="btn secondary" data-action="lesson-back" data-day="${day}" data-step="${step}" ${step===0?'disabled':''}>${icon('left',16)} Назад</button><span>Этап ${step+1} из 11</span>${step===10?`<button class="btn primary" data-route="path">Другие уроки ${icon('arrow',16)}</button>`:`<button class="btn primary" data-action="lesson-next" data-day="${day}" data-step="${step}">${step===9?'Завершить урок':'Продолжить'} ${icon('arrow',16)}</button>`}</div></div></div>`;}
function stepHeading(num,title,desc){return `<div class="stage-header"><div><span class="eyebrow">STEP ${String(num+1).padStart(2,'0')} / 11</span><h2>${e(title)}</h2><p>${e(desc)}</p></div><span class="stage-no">${String(num+1).padStart(2,'0')}</span></div>`;}
function stageView(l,step){const ex=C.getLessonExercises(l),day=l.day;
 if(step===0)return `${stepHeading(0,'Your learning goal','Рабочая ситуация и конкретные результаты обучения')}<div class="learning-goal"><h3>${e(l.title)}</h3><p>${e(l.challenge)}</p></div><span class="eyebrow">By the end of this lesson</span><div class="objectives" style="margin-top:15px">${l.objectives.map(x=>`<div class="objective">${icon('check',17)} <span>${e(x)}</span></div>`).join('')}</div><div class="soft-box" style="margin-top:25px"><strong>Сегодняшний маршрут</strong><p class="muted" style="margin:8px 0 0">Лексика → чтение → аудирование → грамматика → практика → говорение → рабочий кейс. Ориентир — 60–75 минут, без жёсткого таймера.</p></div>`;
 if(step===1)return `${stepHeading(1,'Vocabulary & useful phrases','10 ключевых единиц и 6 выражений, которые действительно понадобятся на работе')}<div class="vocab-grid">${l.vocab.map(v=>{const reveal=ui.revealed.has(v.id),saved=state.saved.includes(v.id);return `<div class="vocab-item ${reveal?'revealed':''}"><div class="word-meta">${e(v.level)} · WORD ${v.id.split('-')[1]}</div><h3 lang="en">${e(v.term)}</h3>${reveal?`<div class="vocab-ru">${e(v.ru)}</div><div class="vocab-def">${e(v.definition)}</div><div class="vocab-example" lang="en">${e(v.example)}</div>`:'<p class="vocab-def">Попробуйте вспомнить значение перед просмотром.</p>'}<div class="vocab-actions"><button class="btn secondary small-btn" data-action="reveal-word" data-id="${v.id}">${reveal?'Скрыть':'Показать'}</button><button class="btn secondary small-btn" data-action="say" data-text="${e(v.term)}">${icon('headphones',15)}</button><button class="btn ${saved?'soft':'secondary'} small-btn" data-action="save-word" data-id="${v.id}" aria-label="${saved?'Убрать из избранного':'Добавить в избранное'}">${icon('heart',15)} ${saved?'Сохранено':'В словарь'}</button></div></div>`;}).join('')}</div><div class="section-heading"><h2>Professional phrases</h2></div><div class="phrase-rows">${l.phrases.map(p=>`<div class="phrase-row"><div><strong lang="en">${e(p.en)}</strong><p>${e(p.ru)}</p></div><button class="icon-btn" data-action="say" data-text="${e(p.en)}" aria-label="Прослушать фразу">${icon('headphones',17)}</button></div>`).join('')}</div>`;
 if(step===2)return `${stepHeading(2,'Read & explore','Нажмите на слово или выражение, чтобы открыть доступную словарную справку')}<h3>${e(l.reading.title)}</h3><p class="muted">Авторский учебный текст · ${l.reading.text.trim().split(/\s+/).length} words</p>${ui.lookup?lookupPanel(ui.lookup):''}<article class="reading-article" lang="en">${l.reading.text.trim().split(/\n\s*\n|\n/).filter(Boolean).map(p=>`<p>${interactiveParagraph(p)}</p>`).join('')}</article><div class="notice">Переводы доступны для слов из локального словаря. Для неизвестных форм мы честно показываем отсутствие перевода — без случайных догадок.</div>`;
 if(step===3)return `${stepHeading(3,'Reading comprehension','Ответьте на вопросы по прочитанному материалу')}${renderExercises(ex.reading,day)}`;
 if(step===4)return `${stepHeading(4,'Listen to the workplace dialogue','Озвучивание средствами браузера; качество голосов зависит от установленной системы')}${audioPlayer(l)}<div class="notice">Сначала прослушайте диалог. Транскрипт можно открыть отдельно для самопроверки.</div><div class="btn-row" style="margin-top:15px"><button class="btn secondary" data-action="toggle-transcript">${ui.transcript?'Скрыть':'Открыть'} транскрипт</button></div>${ui.transcript?dialogueLines(l.dialogue.lines):''}`;
 if(step===5)return `${stepHeading(5,'Listening comprehension','Сначала слушайте диалог, затем отвечайте. Транскрипт доступен после ответов.')}${audioPlayer(l)}${renderExercises(ex.listening,day)}${ex.listening.every(x=>lessonState(day).answers[x.id])?`<button class="btn secondary" data-action="toggle-transcript">${ui.transcript?'Скрыть':'Показать'} транскрипт</button>${ui.transcript?dialogueLines(l.dialogue.lines):''}`:''}`;
 if(step===6)return `${stepHeading(6,'Grammar in context','Только те конструкции, которые нужны для сегодняшнего рабочего сценария')}<h3>${e(l.grammar.title)}</h3><p class="muted">${e(l.grammar.ru)}</p><div class="grammar-callout"><strong>HOW IT WORKS</strong><p lang="en" style="margin:8px 0 0">${e(l.grammar.rule)}</p></div><div class="grammar-examples">${l.grammar.examples.map(x=>`<div class="grammar-example" lang="en">${e(x)}</div>`).join('')}</div><p class="notice"><strong>Common mistake:</strong> ${e(l.grammar.trap)}</p>${renderExercises(ex.grammar,day)}`;
 if(step===7)return `${stepHeading(7,'Active practice','Вспоминайте и применяйте материал, а не только узнавайте правильный ответ')}${renderExercises(ex.practice,day)}<div class="notice">Для перехода выполните минимум три разных упражнения. Ошибки — повод изучить объяснение и повторить попытку.</div>`;
 if(step===8)return `${stepHeading(8,'Speak with confidence','Самостоятельный ответ. Не имитируем автоматическую фонетическую оценку.')}${speakingPanel(l,'lesson')}`;
 if(step===9)return `${stepHeading(9,'Your workplace challenge','Примените сегодняшний материал в реальной профессиональной задаче')}<div class="challenge-box"><span class="eyebrow">Real-world task</span><h3>${e(l.challenge)}</h3><p class="muted" lang="en">${e(l.writing.prompt)}</p></div>${writingPanel(l)}`;
 return summary(l);
}
function interactiveParagraph(p){const phrases=[...lex.keys()].filter(x=>x.includes(' ')).sort((a,b)=>b.length-a.length);const tokens=p.match(/[\p{L}\p{N}]+(?:[’'-][\p{L}\p{N}]+)*|[^\p{L}\p{N}]+/gu)||[];const out=[];let i=0;while(i<tokens.length){if(!/[\p{L}\p{N}]/u.test(tokens[i])){out.push(e(tokens[i++]));continue;}
 let found=null,count=0;for(const phrase of phrases){const parts=phrase.split(/\s+/);if(parts.length>5)continue;const candidate=tokens.slice(i,i+parts.length*2-1).join('');if(C.normalize(candidate)===phrase){found=candidate;count=parts.length*2-1;break;}}
 if(found){out.push(`<button class="reading-word" data-action="lookup" data-term="${e(found)}" title="Выражение — перевод" aria-label="Перевод: ${e(found)}">${e(found)}</button>`);i+=count;}
 else{const word=tokens[i++];out.push(`<button class="reading-word" data-action="lookup" data-term="${e(word)}" title="Нажмите, чтобы найти перевод" aria-label="Перевод: ${e(word)}">${e(word)}</button>`);}}
 return out.join('');}
function lookupPanel(term){const key=C.normalize(term),w=lex.get(key),translation=w?.ru||common[key];const item=w;return `<div class="lookup-card"><div class="row between wrap"><div><span class="eyebrow">Dictionary · contextual lookup</span><h3 lang="en">${e(term)}</h3></div><button class="icon-btn" data-action="lookup-clear" aria-label="Закрыть словарь">${icon('close')}</button></div>${translation?`<p style="color:var(--accent);font-weight:730;margin:8px 0">${e(translation)}</p>`:`<p class="muted">Для этой формы нет проверенного перевода в офлайн-словаре. Посмотрите контекст и попробуйте определить значение самостоятельно.</p>`}${item?`<p lang="en">${e(item.definition)}</p><p class="tip" lang="en">${e(item.example)}</p><div class="btn-row"><button class="btn small-btn soft" data-action="save-word" data-id="${item.id}">${icon('heart',15)} ${state.saved.includes(item.id)?'Убрать из избранного':'Сохранить слово'}</button><button class="btn small-btn secondary" data-action="say" data-text="${e(item.term)}">${icon('headphones',15)} Произнести</button></div>`:''}</div>`;}
function dialogueLines(lines){return `<div class="transcript-panel"><span class="eyebrow">Transcript</span><div class="dialogue-lines" style="margin-top:14px" lang="en">${lines.map(line=>`<div class="dialogue-line"><div class="speaker-avatar">${e(line.speaker.slice(0,2).toUpperCase())}</div><div class="dialogue-bubble"><strong>${e(line.speaker)}</strong>${e(line.text)}</div></div>`).join('')}</div></div>`;}
function audioPlayer(l){return `<div class="audio-box"><span class="eyebrow">LISTENING STUDIO · DAY ${l.day}</span><h3>${e(l.dialogue.title)}</h3><p>Синтез речи воспроизводит авторский диалог по репликам. Это не запись живых носителей и не тренировка конкретного акцента.</p><div class="audio-wave ${ui.playback?'playing':''}">${Array.from({length:24},(_,i)=>`<span style="--h:${8+(i*7%24)}px;--d:-${i%8/10}s"></span>`).join('')}</div><div class="btn-row"><button class="btn primary" data-action="play-dialogue" data-day="${l.day}">${icon('play',16)} ${ui.playback?'Перезапустить':'Прослушать диалог'}</button><button class="btn secondary" data-action="stop-audio">Остановить</button><button class="btn secondary" data-action="say" data-text="${e(l.dialogue.lines[0].text)}">${icon('repeat',16)} 1-я реплика</button></div><p style="margin:14px 0 0">${ui.ttsSupported?'Используется встроенный TTS браузера. Поддержка и голоса зависят от ОС.':'Этот браузер не поддерживает синтез речи. Транскрипт доступен как текстовая альтернатива.'}</p></div>`;}
function renderExercises(list,day){return `<div class="exercise-list">${list.map((q,i)=>renderExercise(q,day,i)).join('')}</div>`;}
function feedback(ans,q){if(!ans)return '';const correct=ans.correct;return `<div class="feedback ${correct?'correct':'wrong'}" role="status">${icon(correct?'check':'info',18)}<div><strong>${correct?'Верно!':'Нужна ещё одна попытка'}</strong>${q.explanation?e(q.explanation):''}${!correct&&q.type==='choice'?`<br><strong>Правильный ответ: ${e(q.options[q.answer])}</strong>`:''}${!correct&&q.type==='fill'?`<br><strong>Ответ: ${e(q.answers[0])}</strong>`:''}${!correct&&q.type==='builder'?`<br><strong lang="en">${e(q.answer)}</strong>`:''}</div></div>`;}
function renderExercise(q,day,i){const saved=lessonState(day).answers[q.id],chosen=ui.selection[q.id],valid=!!saved;let inner='';
 if(q.type==='choice')inner=`<div class="options" role="radiogroup" aria-label="Варианты ответа">${q.options.map((o,j)=>`<label class="option ${String(chosen)===String(j)?'selected':''} ${valid&&q.answer===j?'checked correct':''} ${valid&&saved.answer==j&&q.answer!==j?'checked wrong':''}"><input type="radio" name="pick-${e(q.id)}" value="${j}" ${String(chosen)===String(j)?'checked':''}><span>${e(o)}</span></label>`).join('')}</div><div class="btn-row"><button class="btn primary small-btn" data-action="submit-exercise" data-id="${q.id}" data-day="${day}">${saved?'Повторить проверку':'Проверить ответ'}</button></div>`;
 else if(q.type==='fill')inner=`<div class="form-inline"><input class="field" data-draft="${q.id}" aria-label="Введите пропущенное выражение" placeholder="Your answer…" value="${e(ui.drafts[q.id]??'')}" autocomplete="off"><button class="btn primary" data-action="submit-exercise" data-id="${q.id}" data-day="${day}">Проверить</button></div>`;
 else if(q.type==='match'){const options=[...q.items].reverse();inner=`<div class="match-grid">${q.items.map(x=>`<div class="match-row"><div class="match-label" lang="en">${e(x.term)}</div><select class="select" data-match="${q.id}" data-term="${x.id}" aria-label="Перевод для ${e(x.term)}"><option value="">Выберите перевод</option>${options.map(y=>`<option value="${y.id}" ${ui.selection[q.id+'-'+x.id]===y.id?'selected':''}>${e(y.ru)}</option>`).join('')}</select></div>`).join('')}</div><div class="btn-row"><button class="btn primary small-btn" data-action="submit-exercise" data-id="${q.id}" data-day="${day}">Проверить соответствия</button></div>`;}
 else if(q.type==='builder'){const tokens=q.answer.match(/\S+/g)||[],selected=ui.builders[q.id]||[],pool=tokens.map((word,index)=>({word,index})).sort((a,b)=>a.word.localeCompare(b.word)).reverse();inner=`<div class="builder-area" aria-live="polite">${selected.length?selected.map((idx,i)=>`<button class="word-chip chosen" data-action="builder-remove" data-id="${q.id}" data-index="${i}">${e(tokens[idx])} ×</button>`).join(''):'<span class="muted small">Нажимайте на слова в правильном порядке</span>'}</div><div class="chips-pool">${pool.filter(t=>!selected.includes(t.index)).map(t=>`<button class="word-chip" data-action="builder-add" data-id="${q.id}" data-index="${t.index}">${e(t.word)}</button>`).join('')}</div><div class="btn-row"><button class="btn primary small-btn" data-action="submit-exercise" data-id="${q.id}" data-day="${day}">Проверить порядок</button><button class="btn secondary small-btn" data-action="builder-clear" data-id="${q.id}">Очистить</button></div>`;}
 else if(q.type==='self')inner=`<textarea class="textarea" data-draft="${q.id}" aria-label="Ваш открытый ответ" placeholder="Write your own answer in English…">${e(ui.drafts[q.id]||'')}</textarea><div class="btn-row" style="margin-top:12px"><button class="btn secondary small-btn" data-action="self-reveal" data-id="${q.id}">Показать образец и критерии</button>${ui.revealed.has(q.id)?`<button class="btn primary small-btn" data-action="self-complete" data-id="${q.id}" data-day="${day}">Я сравнил(а) свой ответ</button>`:''}</div>${ui.revealed.has(q.id)?`<div class="model-answer" lang="en" style="margin-top:14px">${e(q.sample)}</div><p class="muted small" style="margin-top:12px">${e(q.explanation||'Сверьте смысл и вежливость. Это самооценка, не автоматический балл.')}</p>`:''}${lessonState(day).writing?.[q.id]?`<div class="feedback info">Самопроверка отмечена. Ответ не оценивался автоматически.</div>`:''}`;
 return `<div class="question" data-question="${q.id}"><div class="question-top"><span>${String(i+1).padStart(2,'0')}</span><span>· ${e(q.label)} ${q.type==='self'?'(самопроверка)':''}</span></div><h3 lang="en">${e(q.q)}</h3>${inner}${feedback(saved,q)}</div>`;}
function speakingPanel(l,context){const record=lessonState(l.day).speaking, done=!!record?.practised;const draft=ui.drafts[`speak-${context}-${l.day}`]??record?.text??'';const ready=ui.revealed.has(`speak-${context}-${l.day}`);return `<div class="challenge-box"><span class="eyebrow">Role play · Academic Support</span><h3 lang="en">${e(l.speaking.prompt)}</h3><p class="muted">Ответьте вслух на английском. Пример — только после собственной попытки.</p></div><div class="btn-row" style="margin-bottom:14px"><button class="btn secondary" data-action="say" data-text="${e(l.speaking.prompt)}">${icon('headphones',16)} Прослушать задание</button><button class="btn secondary" data-action="record-toggle">${icon('mic',16)} ${ui.recording?'Остановить запись':'Записать голос'}</button><button class="btn secondary" data-action="speech-recognize">${icon('mic',16)} Распознать речь</button></div>${ui.micStatus?`<div class="notice" role="status" style="margin-bottom:14px">${e(ui.micStatus)}</div>`:''}${ui.recordUrl?`<audio class="recorded-audio" controls src="${e(ui.recordUrl)}" aria-label="Прослушать свою запись"></audio>`:''}<label class="field-label" for="speaking-text">Что вы сказали? (можно напечатать или вставить распознанный текст)</label><textarea id="speaking-text" class="textarea" data-draft="speak-${context}-${l.day}" lang="en" placeholder="My response…">${e(draft)}</textarea><div class="btn-row" style="margin-top:12px"><button class="btn secondary" data-action="speak-reveal" data-day="${l.day}" data-context="${context}">Показать эталон</button><button class="btn primary" data-action="speak-complete" data-day="${l.day}" data-context="${context}" ${!ready?'disabled title="Сначала сравните ответ с эталоном"':''}>${done?'Практика пройдена ✓':'Отметить практику'}</button></div>${ready?`<div class="model-answer" style="margin:15px 0" lang="en">${e(l.speaking.sample)}</div><h3>Проверьте себя по критериям</h3><div class="rubric">${l.speaking.criteria.map((x,i)=>`<label class="rubric-item"><input type="checkbox" data-rubric="speaking-${l.day}-${i}"><span>${e(x)}</span></label>`).join('')}</div><p class="muted small">Это самостоятельная оценка содержания и вежливости. Распознавание речи не измеряет фонетику, акцент или беглость надёжным способом.</p>`:''}${done?`<div class="feedback correct">Практика сохранена. Это факт выполнения, а не объективная оценка speaking.</div>`:''}`;}
function writingPanel(l){const rec=lessonState(l.day);const text=ui.drafts[`write-${l.day}`]??rec.writing?.text??'';const shown=ui.revealed.has(`write-${l.day}`);return `<label class="field-label" for="writing-answer">Your professional response</label><textarea id="writing-answer" class="textarea" data-draft="write-${l.day}" placeholder="Dear colleague, …" lang="en">${e(text)}</textarea><div class="btn-row" style="margin-top:12px"><button class="btn secondary" data-action="writing-reveal" data-day="${l.day}">Показать образец</button><button class="btn primary" data-action="writing-complete" data-day="${l.day}" ${!shown?'disabled title="Сравните свой ответ с образцом"':''}>${rec.writing?.practised?'Самопроверка выполнена ✓':'Отметить самопроверку'}</button></div>${shown?`<div class="model-answer" style="margin-top:16px" lang="en">${e(l.writing.sample)}</div><div class="rubric">${l.writing.criteria.map((crit,i)=>`<label class="rubric-item"><input type="checkbox"><span>${e(crit)}</span></label>`).join('')}</div><p class="muted small">Пример — не единственный возможный ответ. Оценивайте ясность, точность и профессиональный тон самостоятельно.</p>`:''}${rec.writing?.practised?`<div class="feedback info">Рабочая задача сохранена как выполненная (без автоматической оценки письма).</div>`:''}`;}
